SELECT a.slug,a.kind,l.locale,l.version,l.published_version,(l.draft_json::jsonb = r.document_json::jsonb) AS draft_matches_public FROM guide_articles a LEFT JOIN guide_article_locales l ON l.article_id=a.id LEFT JOIN guide_article_revisions r ON r.article_locale_id=l.id AND r.version=l.published_version WHERE a.slug IN ('ai-term-prompt-engineering','ai-term-context-engineering','ai-term-harness-engineering','ai-term-loop-engineering','ai-term-agentic-engineering','ai-term-vibe-coding','ai-term-spec-driven-development','ai-term-llmops','ai-term-agentops','ai-term-prompt-chaining','ai-term-artificial-intelligence','ai-term-machine-learning','ai-term-deep-learning','ai-term-generative-ai','what-is-a-large-language-model','ai-term-foundation-model','ai-term-transformer','ai-term-mixture-of-experts','ai-term-small-language-model','ai-term-model-parameters','ai-term-token','ai-term-tokenization','ai-context-window-explained','ai-term-system-prompt','ai-term-few-shot-prompting','ai-term-zero-shot-prompting','ai-term-in-context-learning','ai-term-context-compaction','ai-term-context-rot','ai-term-agent-memory','ai-agents-explained','ai-term-agent-loop','ai-term-multi-agent-system','ai-term-subagent','ai-term-agent-orchestration','ai-term-react-reasoning-acting','ai-term-tool-calling','ai-term-model-context-protocol','ai-term-agent2agent-protocol','ai-term-agent-skills','ai-term-retrieval-augmented-generation','ai-term-agentic-rag','ai-term-graph-rag','ai-term-embedding','ai-term-vector-database','ai-term-semantic-search','ai-term-hybrid-search','ai-term-reranking','ai-term-chunking','ai-term-knowledge-graph','ai-term-pretraining','ai-term-fine-tuning','ai-term-supervised-fine-tuning','ai-term-rlhf','ai-term-direct-preference-optimization','ai-term-lora','ai-term-knowledge-distillation','ai-term-quantization','ai-reasoning-models-explained','ai-term-test-time-compute','ai-term-prompt-caching','ai-term-evals','ai-term-benchmark','ai-term-llm-as-a-judge','ai-hallucination-fact-check','ai-term-prompt-injection','ai-term-jailbreak','ai-term-guardrails','ai-term-sandbox','ai-term-human-in-the-loop','ai-term-red-teaming','ai-term-multimodal-ai','ai-term-diffusion-model','ai-term-text-to-image','ai-term-text-to-video','ai-term-automatic-speech-recognition','ai-term-text-to-speech','ai-term-deepfake','ai-term-open-weights','ai-term-open-source-ai','ai-term-content-credentials','ai-terms-index','ai-glossary-50-terms') ORDER BY a.slug,l.locale;
